VALUES ('AMLTRIX-TECH-T0002',1,NULL,'AMLTRIX_TECHNIQUE','T0002',
        '中介促进转让','TECHNIQUE',
        NULL,'通过插入共谋或无意中的中介，犯罪分子增加了多个交易步骤，使非法资金与资金来源疏远，使调查人员追踪最终受益者变得更加困难。这是中介促进转移的主要目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":2}],"techniqueSheetRow":6},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
