VALUES ('AMLTRIX-TECH-T0003',1,NULL,'AMLTRIX_TECHNIQUE','T0003',
        '加密货币混合','TECHNIQUE',
        NULL,'犯罪分子利用混合器将非法资金与合法存款混合在池化或去中心化协议中，明确切断源头与目的地之间的链上踪迹。这种策略使非法收益与其来源保持距离，体现了核心层叠策略。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":3}],"techniqueSheetRow":7},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
