     definition,constraints,status,created_by)
VALUES ('AMLTRIX-TECH-T0004',1,NULL,'AMLTRIX_TECHNIQUE','T0004',
        '现金存款','TECHNIQUE',
        NULL,'现金存款是将非法资金引入正式银行体系的主要方式，通常通过将存款结构设计得略低于报告门槛。这种技术通过在洗钱的早期阶段将犯罪所得与合法账户合并，降低了即时被发现的风险。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"04 放置","row":2}],"techniqueSheetRow":10},"tacticCodes":["PLACEMENT"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
