VALUES ('AMLTRIX-TECH-T0007.001',1,NULL,'AMLTRIX_TECHNIQUE','T0007.001',
        '非法古董贸易','SUB_TECHNIQUE',
        'AMLTRIX-TECH-T0007','非法古物贸易涉及反复跨境买卖文物，估价纵，伪造来源，篡改所有权记录以掩盖其犯罪来源。这种复杂性使得追踪底层非法资金极为困难，体现了典型的层叠过程。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":10}],"techniqueSheetRow":16},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
