VALUES ('AMLTRIX-TECH-T0013',1,NULL,'AMLTRIX_TECHNIQUE','T0013',
        '非正式价值转移系统','TECHNIQUE',
        NULL,'IVTS明确绕过了正式的银行监管，通过依赖基于个人信任或非公开渠道，规避了KYC要求，为犯罪分子提供了无监管的跨境转移非法资金的入口。使用IVTS的主要目的是避免官方金融渠道中的标准反洗钱管控。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":5},{"sheet":"04 放置","row":6},{"sheet":"05 离析","row":18},{"sheet":"07 资产保护","row":3},{"sheet":"08 操作规避","row":2}],"techniqueSheetRow":37},"tacticCodes":["ACCESS_FACILITATION","PLACEMENT","LAYERING","ASSET_PROTECTION","OPERATION_EVASION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
