VALUES ('AMLTRIX-TECH-T0016.003',1,NULL,'AMLTRIX_TECHNIQUE','T0016.003',
        '汇款分拆','SUB_TECHNIQUE',
        'AMLTRIX-TECH-T0016','汇款分拆用于将非法资金引入金融系统，通过保持单个转账低于报告门槛，并以不同的发款人身份分散。这降低了资金进入合法渠道时的直接检测风险。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"04 放置","row":12}],"techniqueSheetRow":61},"tacticCodes":["PLACEMENT"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
