VALUES ('AMLTRIX-TECH-T0018',1,NULL,'AMLTRIX_TECHNIQUE','T0018',
        '网络游戏货币兑换','TECHNIQUE',
        NULL,'犯罪分子用非法资金购买游戏内货币或物品，然后在多个账户或辖区间交易或转售，以掩盖资金的原始来源。这形成了复杂的交易链，使所得资金与犯罪来源保持距离。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":23}],"techniqueSheetRow":65},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
