VALUES ('AMLTRIX-TECH-T0020',1,NULL,'AMLTRIX_TECHNIQUE','T0020',
        '加密货币挖矿','TECHNIQUE',
        NULL,'犯罪分子利用非法资金结算采矿费用，实际上获得了没有交易记录的新铸币，从而切断了原始的资金流向。这是一种有意的叠层策略，旨在将收益与非法来源区分开来。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":24}],"techniqueSheetRow":68},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
