VALUES ('AMLTRIX-TECH-T0021',1,NULL,'AMLTRIX_TECHNIQUE','T0021',
        '内部促进','TECHNIQUE',
        NULL,'共谋的内部人员从内部破坏机构反洗钱管控，绕过KYC检查和正常监管，使犯罪分子能够在极少审查的情况下存入和转移非法资金。这为金融系统创造了直接的入口，绕过了标准的合规流程。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":9}],"techniqueSheetRow":70},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
