VALUES ('AMLTRIX-TECH-T0023',1,NULL,'AMLTRIX_TECHNIQUE','T0023',
        '身份控','TECHNIQUE',
        NULL,'通过伪造、盗窃或伪造身份，犯罪分子绕过KYC和负面筛查，以最少的审查开设或维持账户，直接进入金融系统进行洗钱。这构成了身份控的主要目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":10}],"techniqueSheetRow":72},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
