VALUES ('AMLTRIX-TECH-T0028',1,NULL,'AMLTRIX_TECHNIQUE','T0028',
        '电子商务与市场控','TECHNIQUE',
        NULL,'犯罪分子利用电子商务和市场控，伪造或夸大在线销售、支付或退款，将非法资金分散到多个交易和平台，从而切断与非法来源的直接联系。将非法收益与合法销售流混为一谈，明确掩盖了资金的真实来源，构成了核心的层叠策略。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":29}],"techniqueSheetRow":80},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
