VALUES ('AMLTRIX-TECH-T0029',1,NULL,'AMLTRIX_TECHNIQUE','T0029',
        '工资扣除贷款还款','TECHNIQUE',
        NULL,'这种方式将正式贷款工具重新利用，将非法资金重新引入法律金融体系，使其看起来像普通的工资扣除。工资还款计划的结构化掩盖了资金非典型来源，从而通过将犯罪所得融入合法收入流而合法化。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"06 整合","row":20}],"techniqueSheetRow":81},"tacticCodes":["INTEGRATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
