VALUES ('AMLTRIX-TECH-T0030',1,NULL,'AMLTRIX_TECHNIQUE','T0030',
        '贸易转移','TECHNIQUE',
        NULL,'贸易转移利用复杂的航运路线、多重中介机构和伪造的贸易文件，制造出众多交易层面，掩盖非法资金与其犯罪来源之间的联系。通过将合法与非法商品及支付在不同司法管辖区间混淆，这种技术大大增加了调查人员追踪和归属收益的困难。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":30}],"techniqueSheetRow":82},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
