VALUES ('AMLTRIX-TECH-T0032',1,NULL,'AMLTRIX_TECHNIQUE','T0032',
        '即时交换服务','TECHNIQUE',
        NULL,'即时交换服务允许在多个法定或加密资产之间快速、反复地交换，形成众多交易步骤以掩盖非法资金的来源。这种迭代转换过程是主要战略目标，明确切断清晰的审计轨迹，追溯到犯罪源头。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":31}],"techniqueSheetRow":84},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
