VALUES ('AMLTRIX-TECH-T0040',1,NULL,'AMLTRIX_TECHNIQUE','T0040',
        '基金目的的虚假陈述','TECHNIQUE',
        NULL,'通过将非法收益错误地标注为礼物、慈善捐赠或其他无害的支付，犯罪分子绕过了标准的尽职调查和审查。这种虚假陈述使他们能够开设账户、转账或进行其他银行活动而不触发红旗，有效保障了金融系统的进入和持续访问。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":16}],"techniqueSheetRow":93},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
