VALUES ('AMLTRIX-TECH-T0042',1,NULL,'AMLTRIX_TECHNIQUE','T0042',
        '承载乐器','TECHNIQUE',
        NULL,'持票人工具消除了正式的所有权记录，使犯罪分子能够隐藏真正的实益所有人或非法收益的来源。这是主要目标，因为匿名性是使用这些工具的核心。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"02 隐蔽机制","row":12}],"techniqueSheetRow":96},"tacticCodes":["CONCEALMENT"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
