VALUES ('AMLTRIX-TECH-T0043',1,NULL,'AMLTRIX_TECHNIQUE','T0043',
        '保险箱','TECHNIQUE',
        NULL,'犯罪分子将非法资产实体存放在保险箱中，通常以虚假或模糊身份存在，从而避免进入典型账户记录，避免直接监管反洗钱。这种刻意的策略使侦测变得复杂，便于匿名存款或取款，并维护资产及其受益人之间的秘密性。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"08 操作规避","row":15}],"techniqueSheetRow":97},"tacticCodes":["OPERATION_EVASION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
