VALUES ('AMLTRIX-TECH-T0045.003',1,NULL,'AMLTRIX_TECHNIQUE','T0045.003',
        '艺术市场控','SUB_TECHNIQUE',
        'AMLTRIX-TECH-T0045','连续或夸大的艺术品销售形成复杂的交易链，使非法资金与其来源疏远，阻碍调查人员追溯所得资金至犯罪来源的能力。这是艺术市场纵的主要层次目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":38}],"techniqueSheetRow":102},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
        'ACTIVE','migration-v46')
