VALUES ('AMLTRIX-TECH-T0051',1,NULL,'AMLTRIX_TECHNIQUE','T0051',
        '腐败','TECHNIQUE',
        NULL,'腐败是一种前置犯罪，指官员或权力人员滥用职权或影响力非法获取资金。这构成了非法收益的初始来源，随后必须洗钱。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"01 非法获取","row":7}],"techniqueSheetRow":114},"tacticCodes":["ILLEGAL_ACQUISITION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
