VALUES ('AMLTRIX-TECH-T0071',1,NULL,'AMLTRIX_TECHNIQUE','T0071',
        '循环信用证','TECHNIQUE',
        NULL,'犯罪分子在多家空壳公司和银行之间轮换信用证，形成复杂的贸易融资交易链，掩盖审计追踪，并使非法资金远离其来源。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":68}],"techniqueSheetRow":162},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
