VALUES ('AMLTRIX-TECH-T0072',1,NULL,'AMLTRIX_TECHNIQUE','T0072',
        '出货前财务控','TECHNIQUE',
        NULL,'通过用伪装成合法出口收益的非法资金偿还预发货融资，犯罪分子实际上将非法资本与合法贸易交易合并，完成洗钱过程，借着成功出口销售的幌子完成。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"06 整合","row":41}],"techniqueSheetRow":163},"tacticCodes":["INTEGRATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
