VALUES ('AMLTRIX-TECH-T0073',1,NULL,'AMLTRIX_TECHNIQUE','T0073',
        '第三方支付','TECHNIQUE',
        NULL,'第三方支付明确引入了一个或多个额外步骤——通过外部个人或实体——在犯罪分子与非法资金之间，使审计追踪变得分散，使得资金难以追溯到其犯罪来源。这种额外的交易复杂性是分层的标志。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":69}],"techniqueSheetRow":164},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
