VALUES ('AMLTRIX-TECH-T0076',1,NULL,'AMLTRIX_TECHNIQUE','T0076',
        '账户泄露','TECHNIQUE',
        NULL,'通过泄露合法客户账户，犯罪分子绕过了标准的KYC和AML检查，获得了在既定档案下直接使用权。这是首要目标，确保后续洗钱活动能够不受阻碍地进入金融体系。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":24}],"techniqueSheetRow":170},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
