VALUES ('AMLTRIX-TECH-T0077',1,NULL,'AMLTRIX_TECHNIQUE','T0077',
        '文献收藏控','TECHNIQUE',
        NULL,'文件催收纵是一种基于交易的洗钱手法，伪造的运输文件增加了交易复杂性，掩盖了非法资金的真实来源和流向。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":73}],"techniqueSheetRow":171},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
