INSERT INTO ontology_term
    (term_id,term_version,bank_code,namespace,term_code,term_name,term_type,parent_term_id,
     definition,constraints,status,created_by)
VALUES ('AMLTRIX-TECH-T0078',1,NULL,'AMLTRIX_TECHNIQUE','T0078',
        '联合贸易贷款纵','TECHNIQUE',
        NULL,'犯罪分子利用分散的尽职调查和有限的联合贷款人可见度，策划复杂的多银行融资安排，虚假或伪造贸易文件以掩盖非法资金的真实来源。通过将交易分散到多家参与银行，他们为实际拥有权和交易价值制造了更多层次，使得主动审计和监督变得更加困难。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":74}],"techniqueSheetRow":172},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
