     definition,constraints,status,created_by)
VALUES ('AMLTRIX-TECH-T0079',1,NULL,'AMLTRIX_TECHNIQUE','T0079',
        '反对贸易','TECHNIQUE',
        NULL,'反贸易涉及多个司法管辖区的互惠交换和反复商品运输。当与控的发票结合时，它明确旨在隐藏并区分非法资金的来源。这种多交易方法混淆了监管监管，体现了用于掩盖审计轨迹的分层方法。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":75}],"techniqueSheetRow":173},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
