VALUES ('AMLTRIX-TECH-T0080',1,NULL,'AMLTRIX_TECHNIQUE','T0080',
        '竞标控','TECHNIQUE',
        NULL,'通过纵或扭曲的竞标流程，犯罪分子将非法资金流向看似合法的合同支付或商业收入。这种方法使他们能够将受污染资产与合法资金流合并，完成洗钱的最终整合阶段。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"06 整合","row":44}],"techniqueSheetRow":174},"tacticCodes":["INTEGRATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
