VALUES ('AMLTRIX-TECH-T0082',1,NULL,'AMLTRIX_TECHNIQUE','T0082',
        '共谋型或受控型FI','TECHNIQUE',
        NULL,'犯罪分子故意获取或保留共谋的资金服务业务（MSB）渠道，以规避真正的监管，使非法资金能够以标准资金服务的幌子流动，而不会触发反洗钱管控。这是主要目标，因为它允许直接访问金融系统，同时颠覆合规机制。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":25}],"techniqueSheetRow":176},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
