VALUES ('AMLTRIX-TECH-T0091',1,NULL,'AMLTRIX_TECHNIQUE','T0091',
        '退款','TECHNIQUE',
        NULL,'通过欺诈性地撤销先前已结算的交易，犯罪分子引入了额外的交易步骤，从而掩盖了与原始非法资金的联系。有争议的退款通常通过多个渠道和账户转发，增加了复杂的过程，阻碍了追踪工作，因此分层成为主要目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":83}],"techniqueSheetRow":190},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
