VALUES ('AMLTRIX-TECH-T0093',1,NULL,'AMLTRIX_TECHNIQUE','T0093',
        '篡改财务记录','TECHNIQUE',
        NULL,'篡改财务记录是一种故意删除或伪造官方数据的行为，使犯罪分子通过破坏交易历史或文件的完整性来规避侦查和法医调查。这种战略性方法提升了匿名性，并干扰了调查人员追踪非法资金流向的能力。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"08 操作规避","row":20}],"techniqueSheetRow":192},"tacticCodes":["OPERATION_EVASION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
