VALUES ('AMLTRIX-TECH-T0096',1,NULL,'AMLTRIX_TECHNIQUE','T0096',
        '非正式小额信贷计划','TECHNIQUE',
        NULL,'犯罪分子利用监管松散的轮换储蓄与信用协会（ROSCA）或类似非正式小额信贷计划，作为低门槛的金融入口，规避标准的KYC和反洗钱管控。通过将非法资金与合法会员缴款合并，他们在初始存款阶段规避审查，并掩盖资金的真实来源。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"03 准入便利","row":26}],"techniqueSheetRow":197},"tacticCodes":["ACCESS_FACILITATION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
