VALUES ('AMLTRIX-TECH-T0101',1,NULL,'AMLTRIX_TECHNIQUE','T0101',
        '镜像交易','TECHNIQUE',
        NULL,'配对或抵消镜像交易头寸反复将非法资金在不同账户和司法管辖区间转移，嵌入表面上合法的证券交易中。这种刻意的复杂性正是分层的标志，因为它掩盖了审计线索和实益所有权，使资金与其犯罪来源保持距离。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":87}],"techniqueSheetRow":204},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
