VALUES ('AMLTRIX-TECH-T0102',1,NULL,'AMLTRIX_TECHNIQUE','T0102',
        '抵消交易','TECHNIQUE',
        NULL,'抵消（洗仓或匹配）交易会反复通过几乎同时的买卖订单循环，导致账户余额的净变化极小。这种复杂的交易模式掩盖了可追溯的原始非法来源的联系，体现了一种经典的分层策略，故意分割资金流向，阻碍简单的审计。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":88}],"techniqueSheetRow":205},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
