VALUES ('AMLTRIX-TECH-T0103',1,NULL,'AMLTRIX_TECHNIQUE','T0103',
        '虚构债权人','TECHNIQUE',
        NULL,'通过伪造不存在的负债和相关文件，犯罪分子引入了额外的交易步骤，将非法资金流向掩盖为普通应付款。这种刻意的复杂性掩盖了资金来源与最终收款人之间的联系，体现了一种分层策略以避免被简单发现。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":89}],"techniqueSheetRow":206},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
