VALUES ('AMLTRIX-TECH-T0105',1,NULL,'AMLTRIX_TECHNIQUE','T0105',
        '立即现金转换','TECHNIQUE',
        NULL,'通过将数字或其他可追踪余额转换为实体现金——通常金额低于报告门槛——犯罪分子增加了一层不透明，使追踪非法资金来源变得更加困难。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":90}],"techniqueSheetRow":208},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
