VALUES ('AMLTRIX-TECH-T0111',1,NULL,'AMLTRIX_TECHNIQUE','T0111',
        '基于交易的交易作','TECHNIQUE',
        NULL,'通过多开或少开票、多次重新开票和虚假运输，犯罪分子执行大量复杂的交易，专门掩盖非法资金的真实来源。这反映了将收益与犯罪来源划清界限的核心层次目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":97}],"techniqueSheetRow":222},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
