VALUES ('AMLTRIX-TECH-T0131',1,NULL,'AMLTRIX_TECHNIQUE','T0131',
        '自由港与私人存储','TECHNIQUE',
        NULL,'犯罪分子利用自由港和私人仓储将高价值非法资产安全保护，远离执法部门，防止查获并长期控制其财富。这些设施的不透明性降低了透明度，阻碍了调查，这与保护非法收益整合后的目标完全一致。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"07 资产保护","row":10}],"techniqueSheetRow":249},"tacticCodes":["ASSET_PROTECTION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
