VALUES ('AMLTRIX-TECH-T0132',1,NULL,'AMLTRIX_TECHNIQUE','T0132',
        '银行基础设施控','TECHNIQUE',
        NULL,'通过利用银行内部系统中未被修补的安全漏洞、程序漏洞以及内部勾结，犯罪分子故意规避合规保障和监控控制。这使得他们能够悄无声息地转移非法资金，绕过反洗钱（AML）的触发。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"08 操作规避","row":23}],"techniqueSheetRow":250},"tacticCodes":["OPERATION_EVASION"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
