VALUES ('AMLTRIX-TECH-T0139',1,NULL,'AMLTRIX_TECHNIQUE','T0139',
        '转让定价纵','TECHNIQUE',
        NULL,'通过对公司间交易进行人工定价，犯罪分子构建复杂的多实体金融流，分散并掩盖非法收益，使追踪资金来源变得更加困难。这是利用转让定价纵进行洗钱的主要战略目标。','{"sourceRef":{"source":"AMLTRIX workbooks","release":"2025-05-30","tacticWorkbookSha256":"c691d169f40afb66fb1182cf3bd69574690173db92f0b298c03e0bd6aa62b6a2","indicatorWorkbookSha256":"dbbac9f27449d3a7e642233cc3f9590d8bc3539a7053888e9f48c85ba040f8a3","tacticRows":[{"sheet":"05 离析","row":120}],"techniqueSheetRow":259},"tacticCodes":["LAYERING"],"applicationStatus":"KNOWLEDGE_REGISTERED","observabilityDisposition":"UNASSESSED"}'::jsonb,
