INSERT INTO indicator_definition
    (indicator_code,indicator_name,dimension_code,description,value_type,status,created_by,
     observability_type,source_ref)
VALUES
    ('BG_CASE_EVENT_COUNT','案例基础事件数量','BEHAVIOR','计算进入案例解释流水线的基础事件数量。','NUMBER',
     'ACTIVE','migration-v46','EXECUTABLE',
     '{"source":"BankGraph baseline","algorithm":"INDICATOR_EXPRESSION_EVALUATOR","version":"1.0"}'),
    ('BG_CASE_TRANSACTION_COUNT','案例上下文交易数量','BEHAVIOR','计算结构化案例窗口中的成员和上下文交易数量。','NUMBER',
     'ACTIVE','migration-v46','EXECUTABLE',
     '{"source":"BankGraph baseline","algorithm":"INDICATOR_EXPRESSION_EVALUATOR","version":"1.0"}')
ON CONFLICT (indicator_code) DO UPDATE SET
    indicator_name=EXCLUDED.indicator_name,description=EXCLUDED.description,
    observability_type=EXCLUDED.observability_type,source_ref=EXCLUDED.source_ref,status='ACTIVE';

INSERT INTO indicator_version
    (indicator_code,version,expression,input_schema,threshold_config,algorithm_id,
     algorithm_version,status,effective_from,created_by)
VALUES
    ('BG_CASE_EVENT_COUNT',1,'{"kind":"FIELD","path":"eventCount"}',
     '{"required":["eventCount"]}','{"medium":1,"high":2}',
     'INDICATOR_EXPRESSION_EVALUATOR','1.0','ACTIVE',CURRENT_TIMESTAMP,'migration-v46'),
    ('BG_CASE_TRANSACTION_COUNT',1,'{"kind":"FIELD","path":"transactionCount"}',
     '{"required":["transactionCount"]}','{"medium":1,"high":2}',
     'INDICATOR_EXPRESSION_EVALUATOR','1.0','ACTIVE',CURRENT_TIMESTAMP,'migration-v46')
ON CONFLICT (indicator_code,version) DO UPDATE SET
    expression=EXCLUDED.expression,input_schema=EXCLUDED.input_schema,
    threshold_config=EXCLUDED.threshold_config,algorithm_id=EXCLUDED.algorithm_id,
    algorithm_version=EXCLUDED.algorithm_version,status='ACTIVE';

INSERT INTO knowledge_asset_relation
    (relation_id,source_type,source_code,source_version,relation_type,target_type,target_code,
     target_version,applicability,is_primary,evidence_ref,source_standard_version,effective_from,
     status,review_status,content_sha256,created_by)
SELECT v.relation_id,'INDICATOR',v.indicator_code,'1','INDICATOR_USED_BY_PATTERN',
       'BEHAVIOR_PATTERN',v.pattern_code,'1.0','CASE_EXPLANATION',true,
       '{"source":"BankGraph baseline","version":"1.0"}','BANKGRAPH-1.0',CURRENT_TIMESTAMP,
       'ACTIVE','APPROVED',md5(v.relation_id)||md5(v.relation_id||'bankgraph'),'migration-v46'
FROM (VALUES
    ('KREL-BG-EVENT-COUNT-SHORT-WINDOW','BG_CASE_EVENT_COUNT','SHORT_WINDOW_COMPOSITE'),
    ('KREL-BG-TX-COUNT-SHORT-WINDOW','BG_CASE_TRANSACTION_COUNT','SHORT_WINDOW_COMPOSITE'),
    ('KREL-BG-EVENT-COUNT-TEXT','BG_CASE_EVENT_COUNT','TEXT_AMLTRIX_REPORTED_PATTERN')
) v(relation_id,indicator_code,pattern_code)
WHERE NOT EXISTS (SELECT 1 FROM knowledge_asset_relation r WHERE r.relation_id=v.relation_id);

UPDATE event_pattern_version SET pattern_payload='{
  "patternClass":"RISK",
  "windowSeconds":600,
  "groupBy":["coreAccount"],
  "nodes":[
    {"id":"e1","layer":"BASE_EVENT","eventTypes":["TRANSFER_OUT","CASH_WITHDRAWAL","CASH_DEPOSIT"],"minimum":1},
    {"id":"e2","layer":"BASE_EVENT","eventTypes":["TRANSFER_IN","TRANSFER_OUT","ASSET_PURCHASE"],"minimum":1},
    {"id":"r1","layer":"RISK_EVENT","riskEventType":"SHORT_WINDOW_FUNDS_MOVEMENT_RISK"}
  ],
  "edges":[
    {"source":"e1","target":"e2","type":"PRECEDES","maxSeconds":600},
    {"source":"e2","target":"r1","type":"SUPPORTS","certaintyMode":"PROBABILISTIC"}
  ],
  "minimumEvents":2
}'::jsonb
WHERE pattern_code='SHORT_WINDOW_COMPOSITE' AND version='1.0';

UPDATE event_pattern_version SET pattern_payload='{
  "patternClass":"RISK",
  "observationMode":"REPORTED",
  "nodes":[
    {"id":"e1","layer":"BASE_EVENT","eventTypes":["UNCLASSIFIED_REPORTED_ACTION"],"minimum":1},
    {"id":"t1","layer":"TECHNIQUE_OCCURRENCE","condition":"explicit AMLTRIX code","minimum":1},
    {"id":"r1","layer":"RISK_EVENT","riskEventType":"REPORTED_COMPOSITE_LAUNDERING_SCENARIO"}
  ],
  "edges":[
    {"source":"e1","target":"t1","type":"SUPPORTS","certaintyMode":"REPORTED"},
    {"source":"t1","target":"r1","type":"INFLUENCES","certaintyMode":"PROBABILISTIC"}
  ],
  "minimumExplicitTechniques":1
}'::jsonb
WHERE pattern_code='TEXT_AMLTRIX_REPORTED_PATTERN' AND version='1.0';

